from collections import deque


def transform(grid):
    """Restore 6-cells from the grid's diagonal and centered mirror copies."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    def orbit(start):
        seen = {start}
        q = deque([start])
        while q:
            r, c = q.popleft()
            # The visible object is symmetric across its main diagonal and
            # across the two centered axes (the 32-cell symmetry cropped to 30).
            for p in ((c, r), (31-r, c), (r, 31-c)):
                rr, cc = p
                if 0 <= rr < h and 0 <= cc < w and p not in seen:
                    seen.add(p)
                    q.append(p)
        return seen

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 6:
                continue
            candidates = [grid[rr][cc] for rr, cc in orbit((r, c))
                          if grid[rr][cc] != 6]
            if candidates:
                # In the underlying design all symmetry-related visible cells
                # agree; use the most frequent value to tolerate boundaries.
                out[r][c] = max(set(candidates), key=candidates.count)
    return out


