import sys
from collections import Counter


def transform(grid):
    """Restore masked values by transposition, then complete paired holes locally."""
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    unresolved = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 6}
    for r, c in list(unresolved):
        if grid[c][r] != 6:
            out[r][c] = grid[c][r]
            unresolved.remove((r, c))

    # For holes whose transposed partner is also masked, infer the shared
    # value from the visible border around the symmetric pair/component.
    while unresolved:
        r, c = min(unresolved)
        pair = {(r, c), (c, r)} & unresolved
        counts = Counter()
        for pr, pc in pair:
            for rr in range(max(0, pr-1), min(h, pr+2)):
                for cc in range(max(0, pc-1), min(w, pc+2)):
                    if (rr, cc) not in unresolved and out[rr][cc] != 6:
                        counts[out[rr][cc]] += 1
        value = counts.most_common(1)[0][0] if counts else 0
        for pr, pc in pair:
            out[pr][pc] = value
            unresolved.discard((pr, pc))
    return out


